    }

    FillObsHash();

    networkStats = new NetworkStats *[numNetworks];
    statsManager = new StatsManager(id, STATS_MANAGER_STORE_NAME);
    ndpiStats =
      new nDPIStats(true /* Enable throughput calculation */,
